def longest_common_prefix(iterables):
    """Yield elements of the longest common prefix among given *iterables*.

    >>> ''.join(longest_common_prefix(['abcd', 'abc', 'abf']))
    'ab'

    """
    for group in zip(*iterables):
        first = group[0]
        if all(item == first for item in group):
            yield first
        else:
            break

from math import prod


def _is_scalar(item):
    """Return True for bytes, strings, and non-iterable values."""
    if isinstance(item, (bytes, str)):
        return True
    try:
        iter(item)
    except TypeError:
        return True
    return False


def _flatten(item):
    """Yield the scalar values of *item* in order."""
    if _is_scalar(item):
        yield item
    else:
        for sub in item:
            yield from _flatten(sub)


def _rows(flat, cols):
    """Yield tuples of length *cols* until the values run out."""
    for start in range(0, len(flat) - cols + 1, cols):
        yield tuple(flat[start:start + cols])


def _fold(chunk, dims):
    """Build a nested structure of shape *dims* from a flat list."""
    if not dims:
        return chunk[0]
    size = prod(dims[1:])
    return tuple(
        _fold(chunk[i * size:(i + 1) * size], dims[1:])
        for i in range(dims[0])
    )


def _nest(flat, dims):
    """Yield the items of the outer dimension of shape *dims*."""
    if not dims:
        return
    size = prod(dims[1:])
    for i in range(dims[0]):
        chunk = flat[i * size:(i + 1) * size]
        if len(chunk) < size:
            return
        yield _fold(chunk, dims[1:])


def reshape(matrix, shape):
    """Change the shape of a *matrix*.

    If *shape* is an integer, the matrix must be two dimensional
    and the shape is interpreted as the desired number of columns:

        >>> matrix = [(0, 1), (2, 3), (4, 5)]
        >>> cols = 3
        >>> list(reshape(matrix, cols))
        [(0, 1, 2), (3, 4, 5)]

    If *shape* is a tuple (or other iterable), the input matrix can have
    any number of dimensions. It will first be flattened and then rebuilt
    to the desired shape which can also be multidimensional:

        >>> matrix = [(0, 1), (2, 3), (4, 5)]    # Start with a 3 x 2 matrix

        >>> list(reshape(matrix, (2, 3)))        # Make a 2 x 3 matrix
        [(0, 1, 2), (3, 4, 5)]

        >>> list(reshape(matrix, (6,)))          # Make a vector of length six
        [0, 1, 2, 3, 4, 5]

        >>> list(reshape(matrix, (2, 1, 3, 1)))  # Make 2 x 1 x 3 x 1 tensor
        [(((0,), (1,), (2,)),), (((3,), (4,), (5,)),)]
